  ((SELECT id FROM draft_entities WHERE name = 'Addam of Hull' AND type = 'person'), 'Confesses to Baela', 'Addam explicitly tells Baela he has romantic feelings for her or directly asks her to choose him romantically.', 'Coin flip', 25, 'The awkward romantic tension finally says the quiet part aloud.'),
