  ((SELECT id FROM draft_entities WHERE name = 'Alyn of Hull' AND type = 'person'), 'Rescue Attempt', 'Alyn personally launches or joins an operation whose explicit purpose is rescuing Corlys.', 'Coin flip', 25, 'The severed-finger message gets answered with action.'),
