  ((SELECT id FROM draft_entities WHERE name = 'Alyn of Hull' AND type = 'person'), 'Forgives Corlys', 'Alyn explicitly accepts an apology from Corlys or tells Corlys he forgives him.', 'Long shot', 35, 'The family-healing branch.'),
