  ((SELECT id FROM draft_entities WHERE name = 'Roderick Dustin' AND type = 'person'), 'Ignores Oscar', 'Roddy knowingly disregards or counters a direct battlefield instruction from Oscar.', 'Coin flip', 25, 'Or the old wolf decides he knows better.'),
