  ((SELECT id FROM draft_entities WHERE name = 'Oscar Tully' AND type = 'person'), 'Riverlord Command', 'Oscar gives a battlefield order that is visibly obeyed by a substantial group of Riverland or allied soldiers.', 'Likely', 20, 'The kid keeps commanding adults who could eat him for breakfast.'),
