  ((SELECT id FROM draft_entities WHERE name = 'Alysanne Blackwood' AND type = 'person'), 'Saves Roddy', 'Black Aly uses her bow or another weapon to stop an immediate threat to Roddy.', 'Coin flip', 25, 'The battlefield partnership branch.'),
  ((SELECT id FROM draft_entities WHERE name = 'Alysanne Blackwood' AND type = 'person'), 'Leaves Roddy', 'Black Aly knowingly abandons or refuses to aid Roddy during an immediate danger because of a larger military objective.', 'Coin flip', 25, 'The cold-warrior branch.'),
  ((SELECT id FROM draft_entities WHERE name = 'Alysanne Blackwood' AND type = 'person'), 'Takes the Kill', 'Black Aly personally delivers a fatal blow to a named enemy who could otherwise be captured or spared.', 'Coin flip', 25, 'The Criston follow-up: she finishes the job.'),
  ((SELECT id FROM draft_entities WHERE name = 'Alysanne Blackwood' AND type = 'person'), 'Spare the Enemy', 'Black Aly has a clear chance to kill a named enemy and deliberately chooses not to.', 'Long shot', 35, 'The surprising mercy branch.'),
  ((SELECT id FROM draft_entities WHERE name = 'Torrhen Manderly' AND type = 'person'), 'Money Says No', 'Torrhen explicitly tells Rhaenyra, Daemon, or the council that the crown cannot afford a proposed action or expenditure.', 'Likely', 20, 'The Master of Coin remains the only person fighting arithmetic.'),
  ((SELECT id FROM draft_entities WHERE name = 'Torrhen Manderly' AND type = 'person'), 'Queen Listens', 'Rhaenyra changes or abandons a plan after Torrhen raises a financial objection.', 'Coin flip', 25, 'The impossible dream: someone listens to the accountant.'),
